<"'!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Gravity Well</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #05060a; cursor: crosshair; }
  canvas { display: block; }
  #hud {
    position: fixed; top: 12px; left: 14px;
    font: 12px/1.5 ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    color: #8a93b3; opacity: 0.65; pointer-events: none; user-select: none;
    text-shadow: 0 0 8px #05060a;
  }
  #hud b { color: #c8d0ff; font-weight: 600; }
  #hint {
    position: fixed; bottom: 14px; right: 16px;
    font: 11px/1.5 ui-monospace, monospace; color: #5a6190; opacity: 0.55;
    pointer-events: none; user-select: none;
  }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="hud"><b>GRAVITY WELL</b><br>particles: <span id="count">0</span><br>fps: <span id="fps">0</span></div>
<div id="hint">move mouse to attract · click to burst · scroll to tune mass</div>
<script>
(() => {
  const canvas = document.getElementById('"'c');
  const ctx = canvas.getContext('2d', { alpha: false });
  const countEl = document.getElementById('count');
  const fpsEl = document.getElementById('fps');

  let W = 0, H = 0, DPR = Math.min(window.devicePixelRatio || 1, 2);
  function resize() {
    W = window.innerWidth; H = window.innerHeight;
    canvas.width = Math.floor(W * DPR);
    canvas.height = Math.floor(H * DPR);
    canvas.style.width = W + 'px';
    canvas.style.height = H + 'px';
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  }
  resize();
  window.addEventListener('resize', resize);

  // attractor state
  const mouse = { x: W / 2, y: H / 2, mass: 1400, active: true };
  window.addEventListener('mousemove', (e) => { mouse.x = e.clientX; mouse.y = e.clientY; mouse.active = true; });
  window.addEventListener('mouseleave', () => { mouse.active = false; });
  window.addEventListener('click', (e) => burst(e.clientX, e.clientY));
  window.addEventListener('wheel', (e) => {
    e.preventDefault();
    mouse.mass = Math.max(200, Math.min(6000, mouse.mass - e.deltaY * 1.2));
  }, { passive: false });

  // touch support
  window.addEventListener('touchmove', (e) => {
    if (e.touches[0]) { mouse.x = e.touches[0].clientX; mouse.y = e.touches[0].clientY; mouse.active = true; }
  }, { passive: true });
  window.addEventListener('touchstart', (e) => {
    if (e.touches[0]) burst(e.touches[0].clientX, e.touches[0].clientY);
  }, { passive: true });

  const PALETTE = [
    [120, 180, 255], [180, 140, 255], [120, 255, 220], [255, 200, 130], [255, 130, 200]
  ];

  class Particle {
    constructor() { this.reset(); }
    reset() {
      const edge = Math.floor(Math.random() * 4);
      if (edge === 0) { this.x = Math.random() * W; this.y = -10; }
      else if (edge === 1) { this.x = W + 10; this.y = Math.random() * H; }
      else if (edge === 2) { this.x = Math.random() * W; this.y = H + 10; }
      else { this.x = -10; this.y = Math.random() * H; }
      const c = W / 2, d = H / 2;
      const ang = Math.atan2(d - this.y, c - this.x) + (Math.random() - 0.5) * 0.8;
      const sp = 0.4 + Math.random() * 1.6;
      this.vx = Math.cos(ang) * sp;
      this.vy = Math.sin(ang) * sp;
      this.life = 0;
      this.maxLife = 600 + Math.random() * 800;
      const p = PALETTE[Math.floor(Math.random() * PALETTE.length)];
      this.r = p[0]; this.g = p[1]; this.b = p[2];
      this.size = 0.6 + Math.random() * 1.4;
      this.trail = [];
    }
    step() {
      if (mouse.active) {
        const dx = mouse.x - this.x, dy = mouse.y - this.y;
        const d2 = dx * dx + dy * dy + 120;
        const d = Math.sqrt(d2);
        const f = mouse.mass / d2;
        this.vx += (dx / d) * f * 0.016;
        this.vy += (dy / d) * f * 0.016;
      }
      // slight drag keeps things stable
      this.vx *= 0.9985;
      this.vy *= 0.9985;
      this.x += this.vx;
      this.y += this.vy;

      this.trail.push(this.x, this.y);
      if (this.trail.length > 24) { this.trail.shift(); this.trail.shift(); }

      this.life++;
      if (this.life > this.maxLife ||
          this.x < -60 || this.x > W + 60 || this.y < -60 || this.y > H + 60) {
        this.reset();
      }
    }
    draw() {
      // trail
      const t = this.trail;
      if (t.length >= 4) {
        ctx.beginPath();
        ctx.moveTo(t[0], t[1]);
        for (let i = 2; i < t.length; i += 2) ctx.lineTo(t[i], t[i + 1]);
        ctx.strokeStyle = "'`rgba(${this.r},${this.g},${this.b},0.28)`;
        ctx.lineWidth = this.size * 0.7;
        ctx.lineCap = '"'round';
        ctx.stroke();
      }
      // head
      const speed = Math.min(8, Math.hypot(this.vx, this.vy));
      const glow = 0.5 + speed * 0.06;
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.size + speed * 0.12, 0, Math.PI * 2);
      ctx.fillStyle = "'`rgba(${this.r},${this.g},${this.b},${Math.min(1, glow)})`;
      ctx.fill();
    }
  }

  const N = Math.min(900, Math.floor((W * H) / 2600));
  const parts = Array.from({ length: N }, () => new Particle());

  function burst(x, y) {
    for (const p of parts) {
      const dx = p.x - x, dy = p.y - y;
      const d2 = dx * dx + dy * dy + 1;
      const d = Math.sqrt(d2);
      if (d < 220) {
        const f = (220 - d) * 0.08;
        p.vx += (dx / d) * f;
        p.vy += (dy / d) * f;
      }
    }
  }

  let last = performance.now(), fpsAcc = 0, fpsN = 0, fpsT = 0;
  function frame(now) {
    // motion-blur background
    ctx.fillStyle = '"'rgba(5,6,10,0.22)';
    ctx.fillRect(0, 0, W, H);

    // draw attractor glow
    if (mouse.active) {
      const g = ctx.createRadialGradient(mouse.x, mouse.y, 0, mouse.x, mouse.y, 80);
      g.addColorStop(0, 'rgba(180,200,255,0.18)');
      g.addColorStop(1, 'rgba(180,200,255,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(mouse.x, mouse.y, 80, 0, Math.PI * 2);
      ctx.fill();
    }

    for (const p of parts) { p.step(); p.draw(); }

    const dt = now - last; last = now;
    fpsAcc += dt; fpsN++;
    if (now - fpsT > 500) {
      fpsEl.textContent = Math.round(1000 / (fpsAcc / fpsN));
      fpsAcc = 0; fpsN = 0; fpsT = now;
    }
    countEl.textContent = parts.length;
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
